import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const CreateCoinflipModal = ({ onClose, userId, socket, setBalance }) => {
  const { user } = useAuth();
  const [inventory, setInventory] = useState([]);
  const [selectedItems, setSelectedItems] = useState([]);
  const [minOpponentValue, setMinOpponentValue] = useState(0);
  const [maxOpponentValue, setMaxOpponentValue] = useState(100000);
  const [searchTerm, setSearchTerm] = useState('');
  const [rarityFilter, setRarityFilter] = useState('all');
  const [sortBy, setSortBy] = useState('value_desc');
  const [loading, setLoading] = useState(true);

  // Load user inventory
  useEffect(() => {
    const fetchInventory = async () => {
      try {
        const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/items/user/${userId}/inventory`, {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const data = await response.json();
        setInventory(data.items || []);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching inventory:', error);
        setLoading(false);
      }
    };

    if (userId) {
      fetchInventory();
    }
  }, [userId]);

  const toggleItemSelection = (item) => {
    const existingIndex = selectedItems.findIndex(si => si.itemId === item.itemId);

    if (existingIndex >= 0) {
      // Remove item
      setSelectedItems(selectedItems.filter((_, index) => index !== existingIndex));
    } else {
      // Add item
      setSelectedItems([...selectedItems, item]);
    }
  };

  const getTotalValue = () => {
    return selectedItems.reduce((sum, item) => sum + item.value, 0);
  };

  const handleCreateCoinflip = async () => {
    if (selectedItems.length === 0) {
      alert('Please select at least one item to bet');
      return;
    }

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          selectedItems: selectedItems.map(item => ({
            itemId: item.itemId,
            quantity: item.quantity
          })),
          minOpponentValue,
          maxOpponentValue
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert('Coinflip created successfully!');

        // Update user balance
        if (setBalance) {
          const totalWagered = selectedItems.reduce((sum, item) => sum + item.value, 0);
          setBalance(prev => prev - totalWagered);
        }

        // Notify others
        if (socket) {
          socket.emit('newCoinflip', data);
        }

        onClose();
      } else {
        alert(data.message || 'Failed to create coinflip');
      }
    } catch (error) {
      console.error('Error creating coinflip:', error);
      alert('Error creating coinflip');
    }
  };

  const getRarityClass = (rarity) => {
    switch(rarity) {
      case 'common': return 'badge-common';
      case 'rare': return 'badge-rare';
      case 'epic': return 'badge-epic';
      case 'legendary': return 'badge-legendary';
      case 'mythic': return 'badge-mythic';
      default: return 'badge-common';
    }
  };

  // Filter and sort inventory
  let filteredInventory = [...inventory];

  if (searchTerm) {
    filteredInventory = filteredInventory.filter(item =>
      item.details?.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      item.details?.description.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }

  if (rarityFilter !== 'all') {
    filteredInventory = filteredInventory.filter(item =>
      item.details?.rarity === rarityFilter
    );
  }

  // Sort inventory
  filteredInventory.sort((a, b) => {
    switch(sortBy) {
      case 'value_asc':
        return a.value - b.value;
      case 'value_desc':
        return b.value - a.value;
      case 'name_asc':
        return a.details?.name.localeCompare(b.details?.name);
      case 'name_desc':
        return b.details?.name.localeCompare(a.details?.name);
      default:
        return b.value - a.value;
    }
  });

  if (loading) {
    return (
      <div className="modal-overlay">
        <div className="modal-content">
          <div className="loading-spinner"></div>
          <p>Loading inventory...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="modal-overlay">
      <div className="modal-content large-modal">
        <div className="modal-header">
          <h3>BET ITEMS</h3>
          <button onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          <div className="create-coinflip-container">
            <div className="inventory-section">
              <div className="inventory-controls">
                <input
                  type="text"
                  placeholder="Search items..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="search-input"
                />

                <select
                  value={rarityFilter}
                  onChange={(e) => setRarityFilter(e.target.value)}
                  className="filter-select"
                >
                  <option value="all">All Rarities</option>
                  <option value="common">Common</option>
                  <option value="rare">Rare</option>
                  <option value="epic">Epic</option>
                  <option value="legendary">Legendary</option>
                  <option value="mythic">Mythic</option>
                </select>

                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="sort-select"
                >
                  <option value="value_desc">Value: High to Low</option>
                  <option value="value_asc">Value: Low to High</option>
                  <option value="name_asc">Name: A to Z</option>
                  <option value="name_desc">Name: Z to A</option>
                </select>
              </div>

              <div className="inventory-grid">
                {filteredInventory.map((item, index) => (
                  <div
                    key={`${item.itemId}-${index}`}
                    className={`inventory-item ${selectedItems.some(si => si.itemId === item.itemId) ? 'selected' : ''}`}
                    onClick={() => toggleItemSelection(item)}
                  >
                    <img
                      src={item.details?.imageUrl || '/default-item.png'}
                      alt={item.details?.name}
                      className="inventory-item-image"
                      onError={(e) => {
                        e.target.src = '/default-item.png';
                      }}
                    />
                    <div className="inventory-item-info">
                      <div className="item-name">{item.details?.name}</div>
                      <div className="item-value">{item.value.toLocaleString()} AMP</div>
                      <span className={`badge ${getRarityClass(item.details?.rarity)}`}>
                        {item.details?.rarity}
                      </span>
                      <div className="item-quantity">Qty: {item.quantity}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="selection-section">
              <div className="selected-items">
                <h4>Selected Items ({selectedItems.length})</h4>
                <div className="selected-items-list">
                  {selectedItems.length === 0 ? (
                    <p>No items selected</p>
                  ) : (
                    selectedItems.map((item, index) => (
                      <div key={`${item.itemId}-${index}`} className="selected-item">
                        <img
                          src={item.details?.imageUrl || '/default-item.png'}
                          alt={item.details?.name}
                          className="selected-item-image"
                          onError={(e) => {
                            e.target.src = '/default-item.png';
                          }}
                        />
                        <div className="selected-item-info">
                          <div className="item-name">{item.details?.name}</div>
                          <div className="item-value">{item.value.toLocaleString()} AMP</div>
                        </div>
                        <button
                          className="remove-item-btn"
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedItems(selectedItems.filter((_, i) => i !== index));
                          }}
                        >
                          ×
                        </button>
                      </div>
                    ))
                  )}
                </div>

                <div className="total-wager">
                  Total Wager: <strong>{getTotalValue().toLocaleString()} AMP</strong>
                </div>
              </div>

              <div className="wager-settings">
                <h4>Wager Settings</h4>
                <div className="form-group">
                  <label className="form-label">Minimum Opponent Value</label>
                  <input
                    type="number"
                    value={minOpponentValue}
                    onChange={(e) => setMinOpponentValue(Number(e.target.value))}
                    className="form-control"
                    placeholder="0"
                  />
                </div>

                <div className="form-group">
                  <label className="form-label">Maximum Opponent Value</label>
                  <input
                    type="number"
                    value={maxOpponentValue}
                    onChange={(e) => setMaxOpponentValue(Number(e.target.value))}
                    className="form-control"
                    placeholder="∞"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose}>
            Cancel
          </button>
          <button
            className="btn btn-primary"
            onClick={handleCreateCoinflip}
            disabled={selectedItems.length === 0}
          >
            CREATE COINFLIP ({getTotalValue().toLocaleString()} AMP)
          </button>
        </div>
      </div>
    </div>
  );
};

export default CreateCoinflipModal;
